// UpdateNewValues updates the mutable fields using the new values that were set on create except the ID field.
// Using this option is equivalent to using:
//
//	client.TriggerFire.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(triggerfire.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *TriggerFireUpsertOne) UpdateNewValues() *TriggerFireUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		if _, exists := u.create.mutation.ID(); exists {
			s.SetIgnore(triggerfire.FieldID)
		}
		if _, exists := u.create.mutation.ProjectID(); exists {
			s.SetIgnore(triggerfire.FieldProjectID)
		}
		if _, exists := u.create.mutation.TriggerID(); exists {
			s.SetIgnore(triggerfire.FieldTriggerID)
		}
		if _, exists := u.create.mutation.EventID(); exists {
			s.SetIgnore(triggerfire.FieldEventID)
		}
		if _, exists := u.create.mutation.Subject(); exists {
			s.SetIgnore(triggerfire.FieldSubject)
		}
		if _, exists := u.create.mutation.ActionType(); exists {
			s.SetIgnore(triggerfire.FieldActionType)
		}
		if _, exists := u.create.mutation.ActionIndex(); exists {
			s.SetIgnore(triggerfire.FieldActionIndex)
		}
		if _, exists := u.create.mutation.StartedAt(); exists {
			s.SetIgnore(triggerfire.FieldStartedAt)
		}
		if _, exists := u.create.mutation.Created(); exists {
			s.SetIgnore(triggerfire.FieldCreated)
		}
	}))
	return u
}

